import json,math,heapq,itertools
import numpy as np
from PIL import Image,ImageDraw
from scipy import ndimage as ndi
base=json.load(open('/app/output/planned_strokes.json'))
im=np.array(Image.open('/app/target.png'))
B=im.mean(2)<100
lab,n=ndi.label(B,np.ones((3,3)))
labels={}
for i in range(1,n+1):
 yy,xx=np.where(lab==i)
 if len(xx)>100: labels[(int(xx.min()),int(yy.min()))]=i
# Map expected letters to labels by x-order.
comps=sorted([(x,i) for (x,y),i in labels.items()])
letter_label={l:comps[j][1] for j,l in enumerate('donum')}
DT=ndi.distance_transform_edt(B)

def route_within(letter,start,goal):
 ci=letter_label[letter]
 mask=lab==ci
 # Dijkstra in the target ink, with a gentle preference for the center of thick strokes.
 pq=[(0.0,start)];dist={start:0.0};prev={}
 while pq:
  cost,p=heapq.heappop(pq)
  if cost!=dist[p]:continue
  if p==goal:break
  r,c=p
  for dr in (-1,0,1):
   for dc in (-1,0,1):
    if not (dr or dc):continue
    q=(r+dr,c+dc)
    if not(0<=q[0]<1024 and 0<=q[1]<1024 and mask[q]):continue
    length=math.sqrt(2) if dr and dc else 1.0
    step=length*(1.0+0.10/(DT[q]+0.25))
    new=cost+step
    if new<dist.get(q,1e99):dist[q]=new;prev[q]=p;heapq.heappush(pq,(new,q))
 if goal not in dist:raise RuntimeError((letter,start,goal,'not connected'))
 path=[goal]
 while path[-1]!=start:path.append(prev[path[-1]])
 return path[::-1],dist[goal]

remaining=[]
# Rescore fixed-angle d/o paths with a local nib-angle profile.
for p in base:
 if p['letter'] in 'do':
  remaining.append({**p,'tag':'variable-angle correction'})

# Merge every skeleton trail for n/u/m into one continuous contact path. Any
# connecting segment stays in the glyph's black area, where the added ink is on-target.
for letter in 'num':
 trails=[p['pixel_rc'] for p in base if p['letter']==letter]
 m=len(trails)
 # Endpoint routes are precomputed so a small exact search can select order/directions.
 cache={}
 for i in range(m):
  for flip_i in [0,1]:
   for j in range(m):
    if i==j:continue
    for flip_j in [0,1]:
     a=tuple(trails[i][-1 if flip_i==0 else 0]); b=tuple(trails[j][0 if flip_j==0 else -1])
     if (a,b) not in cache:cache[a,b]=route_within(letter,a,b)
 best=None
 for perm in itertools.permutations(range(m)):
  for flips in itertools.product([0,1],repeat=m):
   cost=0.0; connectors=[]
   for k in range(m-1):
    i,j=perm[k],perm[k+1]
    a=tuple(trails[i][-1 if flips[k]==0 else 0]);b=tuple(trails[j][0 if flips[k+1]==0 else -1])
    route,w=cache[a,b];cost+=w;connectors.append(route)
   if best is None or cost<best[0]:best=(cost,perm,flips,connectors)
 cost,perm,flips,connectors=best
 merged=[]
 for k,(i,flip) in enumerate(zip(perm,flips)):
  t=[tuple(p) for p in trails[i]]
  if flip:t=t[::-1]
  if not merged:merged.extend(t)
  else:
   conn=connectors[k-1]
   # connector is previous-trail end -> next-trail start
   merged.extend(conn[1:]); merged.extend(t[1:])
 remaining.append({'letter':letter,'stroke':0,'tag':'merged continuous path',
                   'pixel_rc':[[int(r),int(c)] for r,c in merged]})
 print(letter,'merged paths',m,'connector cost',round(cost,1),'total pixels',len(merged),'order',perm,'flips',flips)

with open('/app/output/remaining_strokes.json','w') as f:json.dump(remaining,f)
# visualize the merged centerlines on the target
canvas=Image.new('RGB',(1024,1024),(255,255,255));pix=canvas.load()
for y in range(1024):
 for x in range(1024):
  if B[y,x]:pix[x,y]=(230,230,230)
d=ImageDraw.Draw(canvas);cols={'d':(220,20,20),'o':(20,60,230),'n':(20,160,20),'u':(180,0,180),'m':(220,120,0)}
for p in remaining:
 rc=p['pixel_rc'];xy=[(c,r) for r,c in rc]
 d.line(xy,fill=cols[p['letter']],width=2)
